def bloco(lingua):
    i = 0 if lingua == 'pt' else 1
    linhas = []
    for k, v in K.items():
        txt = v[i].replace('\\', '\\\\').replace("'", "\\'")
        linhas.append(f"'{k}':'{txt}'")
    return ',\n'.join(linhas)


src = ARQ.read_text(encoding='utf-8')
# remove um bloco ea.* de execução anterior
# (formato antigo, com o comentário entre a vírgula e a chave, e o atual)
src = re.sub(r",\n/\* atlas-empresas:(pt|en) \*/\n.*?\n/\* fim atlas-empresas \*/", '', src, flags=re.S)
src = re.sub(r" /\* atlas-empresas:(pt|en) \*/,\n.*? /\* fim atlas-empresas \*/", '', src, flags=re.S)
# O comentário fica ANTES da vírgula: tests/test_i18n.py reconhece a chave por "vírgula + aspas", sem nada no meio.
pt_fim = src.index('\n},en:{')
src = src[:pt_fim] + ' /* atlas-empresas:pt */,\n' + bloco('pt') + ' /* fim atlas-empresas */' + src[pt_fim:]
en_fim = src.index('\n}};')
src = src[:en_fim] + ' /* atlas-empresas:en */,\n' + bloco('en') + ' /* fim atlas-empresas */' + src[en_fim:]
ARQ.write_text(src, encoding='utf-8', newline='\n')  # LF, como o resto do repositório
print(len(K), 'chaves em PT e EN')
